$string['panel_isthis_bridge'] = 'Uma ponte traz para o Eguahe o que chega por outra ferramenta (os anúncios do Google ou da Meta, a caixa de admissões ou um formulário que a escola já usa), para que cada família tenha a sua ficha e seja respondida pela caixa de entrada.';
